dtsPropsFor.Availability:
/** Envelope from GET /api/availability. scraped_at null renders the "No data yet" state; start_at is clinic-local ISO with offset (e.g. "2026-07-17T14:30:00-07:00"), scraped_at/latest_attempt_at are UTC ISO. */
  data: { city: string; city_name: string; scraped_at: string | null; latest_attempt_at: string | null; clinics_attempted: number | null; failed_clinics: string[]; window_days: number; timezone: string; clinics_total: number; quiet_hours: { start: string; end: string } | null; slots: Array<{ clinic_name: string; clinic_slug: string | null; city: string; platform: string; rmt_name: string; service_type: string; treatment_name: string; duration_minutes: number; start_at: string; booking_url: string }> };
  /** Active day pill: 0 = today, 1 = tomorrow, n = n days out, or "all". */
  activeWindow: number | "all";
  onWindowChange: (window: number | "all") => void;

dtsPropsFor.CityMenu:
/** Cities on the roster, in display order. */
  cities: Array<{ slug: string; name: string }>;
  /** Selected city slug; null = none chosen (button reads "Choose a city"). */
  value: string | null;
  onChange: (slug: string) => void;

dtsPropsFor.MetaLine:
/** Same envelope Availability takes; scraped_at must be non-null. */
  data: { city: string; city_name: string; scraped_at: string | null; latest_attempt_at: string | null; clinics_attempted: number | null; failed_clinics: string[]; window_days: number; timezone: string; clinics_total: number; quiet_hours: { start: string; end: string } | null; slots: Array<{ clinic_name: string; clinic_slug: string | null; city: string; platform: string; rmt_name: string; service_type: string; treatment_name: string; duration_minutes: number; start_at: string; booking_url: string }> };
  /** Epoch ms used for the "Last updated N minutes ago" math. */
  nowMs: number;
  /** false hides the "all clinics checked" suffix. */
  latestCheckOk: boolean;
  /** Overnight-pause sentence shown as a second line, or null. */
  quietNote: string | null;

dtsPropsFor.SlotGroups:
/** Slots, already sorted soonest-first; grouped into one section per clinic-local day. */
  slots: Array<{ clinic_name: string; clinic_slug: string | null; city: string; platform: string; rmt_name: string; service_type: string; treatment_name: string; duration_minutes: number; start_at: string; booking_url: string }>;
  /** Clinic-local "YYYY-MM-DD", used to label day badges Today/Tomorrow. */
  today: string;
  /** Show a day badge above each day group (the app does this only in the "All" view). */
  showDayBadges: boolean;
